Input: {"question": "When was Donald Macdonell born?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0423-5f232f5587db:d00", "start": 0, "end": 144, "text": "Donald Greenfield MacDonell Donald Greenfield MacDonell (July 2, 1849 – November 12, 1916) was a lawyer and political figure in Ontario, Canada."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0423-5f232f5587db:d00", "start": 145, "end": 245, "text": "He represented Lanark North in the House of Commons of Canada from 1880 to 1882 as a Liberal member."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0423-5f232f5587db:d00", "start": 246, "end": 301, "text": "He was born in Morrisburg, Canada West, the son of A.G."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0423-5f232f5587db:d00", "start": 302, "end": 349, "text": "MacDonell and the grandson of Donald Macdonell."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0423-5f232f5587db:d00", "start": 350, "end": 401, "text": "He was educated at Upper Canada College in Toronto."}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0423-5f232f5587db:d00", "start": 402, "end": 486, "text": "MacDonell was married twice: to Margaret Rosamond in 1875 and to Edith Rose in 1880."}, "D1S7": {"document_number": 1, "doc_id": "ramdocs-0423-5f232f5587db:d00", "start": 487, "end": 525, "text": "He served as reeve of Almonte in 1878."}, "D1S8": {"document_number": 1, "doc_id": "ramdocs-0423-5f232f5587db:d00", "start": 526, "end": 577, "text": "MacDonell was first elected to the House of Commons"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0423-5f232f5587db:d01", "start": 0, "end": 134, "text": "Donald Macdonell (Upper Canada politician) Donald Macdonell (January 17, 1778 – June 13, 1861) was a political figure in Upper Canada."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0423-5f232f5587db:d01", "start": 135, "end": 369, "text": "He was born in Greenfield, near Aberchalder, in Inverness-shire, Scotland in 1778, the son of Alexander Macdonell, and came to Charlottenburgh Township in Upper Canada in 1792 as part of a group of Scottish settlers led by his father."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0423-5f232f5587db:d01", "start": 370, "end": 412, "text": "He studied with John Strachan in Cornwall."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0423-5f232f5587db:d01", "start": 413, "end": 510, "text": "He served with the local militia during the War of 1812, reaching the rank of lieutenant-colonel."}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0423-5f232f5587db:d01", "start": 511, "end": 590, "text": "During the war, his brother John was killed at the Battle of Queenston Heights."}, "D2S6": {"document_number": 2, "doc_id": "ramdocs-0423-5f232f5587db:d01", "start": 591, "end": 605, "text": "After the war,"}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0423-5f232f5587db:d02", "start": 0, "end": 28, "text": "a member of the Labor Party."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0423-5f232f5587db:d02", "start": 29, "end": 83, "text": "He was general secretary of the AWU from 1900 to 1911."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0423-5f232f5587db:d02", "start": 84, "end": 275, "text": "In 1901 he was elected to the New South Wales Legislative Assembly as the Labor member for Cobar, serving until 1911; he was Minister for Agriculture and Colonial Secretary from 1910 to 1911."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0423-5f232f5587db:d02", "start": 276, "end": 312, "text": "Macdonell died in Melbourne in 1911."}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0423-5f232f5587db:d02", "start": 313, "end": 425, "text": "Donald Macdonell (Australian politician) Donald Macdonell (1862 – 26 October 1911) was an Australian politician."}, "D3S6": {"document_number": 3, "doc_id": "ramdocs-0423-5f232f5587db:d02", "start": 426, "end": 593, "text": "Born at Stuart Mill near St Arnaud, Victoria, to Scottish-born farmer and shearer Alexander Macdonell, he helped on his father's farm as a child and moved to New South"}, "D4S1": {"document_number": 4, "doc_id": "ramdocs-0423-5f232f5587db:d03", "start": 0, "end": 444, "text": "Macdonell ( 1862–1911 ) by Frank Farrell This article was published : in the Australian Dictionary of Biography , Volume 10 online in 1986 This entry is from the Australian Dictionary of Biography Donald Macdonell ( 1862-1911 ) , shearer , trade unionist and politician , was born in January 1862 at Stuart Mill , Victoria , son of Alexander Macdonell , Scottish migrant of Catholic Highland extraction , and his wife , Christina née McMaster ."}, "D4S2": {"document_number": 4, "doc_id": "ramdocs-0423-5f232f5587db:d03", "start": 445, "end": 566, "text": "His parents were hard working , industrious and frugal and imparted these virtues to Donald and his brother and sisters ."}, "D4S3": {"document_number": 4, "doc_id": "ramdocs-0423-5f232f5587db:d03", "start": 567, "end": 579, "text": "From boyhood"}, "D5S1": {"document_number": 5, "doc_id": "ramdocs-0423-5f232f5587db:d04", "start": 0, "end": 733, "text": "; 2.43 MB 1 reference reference URL https : //collection.sl.nsw.gov.au/record/9BvkaPL9/Zy4VxrxQPEXm7 retrieved 26 July 2021 sex or gender male 0 references country of citizenship Australia 0 references given name Donald 0 references family name Macdonell 0 references date of birth 1862 1 reference stated in Australian Dictionary of Biography Australian Dictionary of Biography ID macdonell-donald-7342 imported from Wikimedia project English Wikipedia retrieved 26 July 2021 place of birth Stuart Mill 1 reference stated in Australian Dictionary of Biography Australian Dictionary of Biography ID macdonell-donald-7342 imported from Wikimedia project English Wikipedia retrieved 26 July 2021 date of death 26 October 1911 Gregorian"}, "D6S1": {"document_number": 6, "doc_id": "ramdocs-0423-5f232f5587db:d05", "start": 0, "end": 648, "text": "Permanent link Page information Concept URI